import { Align } from "@kvisaz/phaser-sugar";
import { ViewElementBuilder } from "../../../assets";
import { emitGamePlayCardBackThemeChange } from "../GamePlayCard/events";
import { getGamePlayCardBackAssetNames } from "../GamePlayCard/themeMapping";

interface IProps {
  scene: Phaser.Scene;
}

export class GamePlayCardBackButton extends Phaser.GameObjects.Container {
  private readonly backAssetNames = getGamePlayCardBackAssetNames();
  private nextBackThemeIndex = 1;
  private currentBackTheme = this.backAssetNames[0];
  private readonly valueText: Phaser.GameObjects.Text;

  constructor(private readonly props: IProps) {
    super(props.scene);
    const builder = new ViewElementBuilder(props.scene);
    const align = new Align();

    const button = builder.buttonSecondary("Рубашка", () => {
      const nextBackTheme = this.backAssetNames[this.nextBackThemeIndex];
      emitGamePlayCardBackThemeChange({
        scene: this.props.scene,
        backAssetName: nextBackTheme,
      });

      this.currentBackTheme = nextBackTheme;
      this.valueText.setText(this.currentBackTheme);
      this.nextBackThemeIndex = (this.nextBackThemeIndex + 1) % this.backAssetNames.length;
    }, {
      fontSizePx: 20,
      paddingY: 5,
    });

    this.valueText = builder.textMain(this.currentBackTheme, {
      color: "#ffffff",
      fontSize: "24px",
    });

    align.anchor(button).bottomTo(this.valueText, 6).centerX(this.valueText);
    this.add([button, this.valueText]);
    props.scene.add.existing(this);
  }
}
