import { typedEmit } from "../../../common/events/typedSub/typedSub";
import { GamePlayCardBackAssetName } from "./themeMapping";
import { GamePlayCardTheme } from "./types";

export const cardEvents = {
  themeFaceChange: "card.theme.face.change",
  themeBackChange: "card.theme.back.change",
} as const;

export interface IGamePlayCardFaceThemeChangeEventData {
  faceAssetName: GamePlayCardTheme;
}

export interface IGamePlayCardBackThemeChangeEventData {
  backAssetName: GamePlayCardBackAssetName;
}

export function emitGamePlayCardFaceThemeChange({
  scene,
  faceAssetName,
}: {
  scene: Phaser.Scene;
  faceAssetName: GamePlayCardTheme;
}): void {
  typedEmit<IGamePlayCardFaceThemeChangeEventData>({
    eventEmitter: scene.events,
    eventName: cardEvents.themeFaceChange,
    data: { faceAssetName },
  });
}

export function emitGamePlayCardBackThemeChange({
  scene,
  backAssetName,
}: {
  scene: Phaser.Scene;
  backAssetName: GamePlayCardBackAssetName;
}): void {
  typedEmit<IGamePlayCardBackThemeChangeEventData>({
    eventEmitter: scene.events,
    eventName: cardEvents.themeBackChange,
    data: { backAssetName },
  });
}
