import { Align } from "@kvisaz/phaser-sugar";
import { ViewElementBuilder } from "../../../assets";
import { emitGamePlayCardFaceThemeChange } from "../GamePlayCard/events";
import { GamePlayCardTheme } from "../GamePlayCard/types";

interface IProps {
  scene: Phaser.Scene;
}

export class GamePlayCardThemeButton extends Phaser.GameObjects.Container {
  private currentTheme: GamePlayCardTheme = GamePlayCardTheme.chibi;
  private readonly valueText: Phaser.GameObjects.Text;

  constructor(private readonly props: IProps) {
    super(props.scene);
    const builder = new ViewElementBuilder(props.scene);
    const align = new Align();

    const button = builder.buttonSecondary("Стиль карт", () => {
      this.currentTheme =
        this.currentTheme === GamePlayCardTheme.chibi
          ? GamePlayCardTheme.classic
          : GamePlayCardTheme.chibi;
      emitGamePlayCardFaceThemeChange({
        scene: this.props.scene,
        faceAssetName: this.currentTheme,
      });
      this.valueText.setText(this.currentTheme);
    }, {
      fontSizePx: 20,
      paddingY: 5,
    });

    this.valueText = builder.textMain(this.currentTheme, {
      color: "#ffffff",
      fontSize: "24px",
    });

    align.anchor(button).bottomTo(this.valueText, 6).centerX(this.valueText);
    this.add([button, this.valueText]);
    props.scene.add.existing(this);
  }
}
